import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Fidelity — dogfood-alert-orchestrator (v1.17-3)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/observability/alert-orchestrator.md","filePath":"quality-reports/observability/alert-orchestrator.md"}'),r={name:"quality-reports/observability/alert-orchestrator.md"};function o(i,e,l,n,c,p){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="fidelity-—-dogfood-alert-orchestrator-v1-17-3" tabindex="-1">Fidelity — dogfood-alert-orchestrator (v1.17-3) <a class="header-anchor" href="#fidelity-—-dogfood-alert-orchestrator-v1-17-3" aria-label="Permalink to &quot;Fidelity — dogfood-alert-orchestrator (v1.17-3)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Prometheus AlertManager style alert orchestrator dogfood, produced by <code>examples/dogfood-alert-orchestrator/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa-lab/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-alertmanager-url" tabindex="-1">Baseline (real mode skipped — no <code>ALERTMANAGER_URL</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-alertmanager-url" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`ALERTMANAGER_URL\`)&quot;">​</a></h2><p>When the harness runs without an AlertManager URL, the real adapter emits <code>ALERTMANAGER_ENV_MISSING</code> for every lifecycle op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-lab/observability/alert</span></span>
<span class="line"><span>version    : 2.0.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 4 (emitMetric noop + evaluateRules / routeAlert / advanceEscalation missing on real)</span></span>
<span class="line"><span>axes       : 7 (common branch — AlertManager is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (3/3)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>11.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>23</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts the 4 ops whose mock path succeeded but whose real path is absent (<code>ALERTMANAGER_ENV_MISSING</code> for the 3 lifecycle ops + <code>ALERTMANAGER_METRIC_NOOP</code> for <code>emitMetric</code>) — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 3 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-alert-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-alert-orchestrator/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ALERTMANAGER_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:9093</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-alert-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When the URL is set but the AlertManager instance has no active alerts, <code>evaluateRules</code> returns an empty array — the same shape the mock returns when no rule matches. The mock / real behave identically for the empty-fire case.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Three provider-neutral ops on <code>AlertOrchestratorAdapter</code> cover the AlertManager alert lifecycle end-to-end.</p><ul><li><code>evaluateRules</code> — evaluate every registered rule against the metric window; return newly fired alerts.</li><li><code>routeAlert</code> — walk the routing tree respecting silences; return the receiver + silenced flag.</li><li><code>advanceEscalation</code> — walk the escalation ladder (L1 30s → L2 5min → L3 30min); return receiver notifications whose after-window has elapsed.</li></ul><p>Plus the <code>emitMetric</code> op (mock only — Prometheus scrapes metrics on its own cadence on the real path) so the mock has data to fire against. <code>emitMetric</code> is excluded from <code>OPS_UNDER_TEST</code> because the real adapter noops it by design, and counting it would over-report divergences.</p><p>Accessor <code>getActive</code> is also present so tests can assert current firing state without wall-clock coupling.</p><h2 id="_10-rules-×-3-routing-×-silence-×-escalation" tabindex="-1">10 rules × 3 routing × silence × escalation <a class="header-anchor" href="#_10-rules-×-3-routing-×-silence-×-escalation" aria-label="Permalink to &quot;10 rules × 3 routing × silence × escalation&quot;">​</a></h2><p>The 10 seeded rules (<code>src/rules/index.ts</code>) span 3 kinds of Prometheus rule shape.</p><table tabindex="0"><thead><tr><th>id</th><th>kind</th><th>metric</th><th>operator</th><th>threshold / window / stddev</th><th>severity</th><th>team</th><th>channel</th></tr></thead><tbody><tr><td><code>rule-http-errors-critical</code></td><td>threshold</td><td><code>http.errors</code></td><td><code>&gt;=</code></td><td>10, 1 sample</td><td>critical</td><td>platform</td><td>pagerduty</td></tr><tr><td><code>rule-latency-degraded</code></td><td>threshold</td><td><code>http.latency.ms</code></td><td><code>&gt;=</code></td><td>500, 3 samples</td><td>warn</td><td>platform</td><td>slack</td></tr><tr><td><code>rule-queue-backpressure</code></td><td>threshold</td><td><code>queue.depth</code></td><td><code>&gt;=</code></td><td>1000, 1 sample</td><td>warn</td><td>data</td><td>slack</td></tr><tr><td><code>rule-disk-usage-high</code></td><td>threshold</td><td><code>disk.usage.percent</code></td><td><code>&gt;=</code></td><td>90, 1 sample</td><td>critical</td><td>infra</td><td>pagerduty</td></tr><tr><td><code>rule-http-5xx-rate</code></td><td>rate</td><td><code>http.errors.total</code></td><td><code>&gt;=</code></td><td>0.5/s, 60s window</td><td>critical</td><td>platform</td><td>pagerduty</td></tr><tr><td><code>rule-request-rate</code></td><td>rate</td><td><code>http.requests.total</code></td><td><code>&gt;=</code></td><td>100/s, 60s window</td><td>info</td><td>platform</td><td>slack</td></tr><tr><td><code>rule-error-rate-per-route</code></td><td>rate</td><td><code>route.errors.total</code></td><td><code>&gt;=</code></td><td>0.1/s, 30s window</td><td>warn</td><td>platform</td><td>slack</td></tr><tr><td><code>rule-memory-rss-anomaly</code></td><td>anomaly</td><td><code>process.memory.rss</code></td><td><code>&gt;=</code></td><td>mean + 3σ</td><td>warn</td><td>infra</td><td>slack</td></tr><tr><td><code>rule-cpu-usage-anomaly</code></td><td>anomaly</td><td><code>process.cpu.percent</code></td><td><code>&gt;=</code></td><td>mean + 3σ</td><td>critical</td><td>infra</td><td>pagerduty</td></tr><tr><td><code>rule-gc-pause-anomaly</code></td><td>anomaly</td><td><code>runtime.gc.pause.ms</code></td><td><code>&gt;=</code></td><td>mean + 2σ</td><td>warn</td><td>platform</td><td>slack</td></tr></tbody></table><p>Routing tree (<code>src/routing/index.ts</code>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root (default)</span></span>
<span class="line"><span>├── severity=critical</span></span>
<span class="line"><span>│   ├── team=platform → pagerduty-platform</span></span>
<span class="line"><span>│   ├── team=infra    → pagerduty-infra</span></span>
<span class="line"><span>│   └── (fallback)    → pagerduty</span></span>
<span class="line"><span>├── severity=warn</span></span>
<span class="line"><span>│   ├── team=platform → slack-platform</span></span>
<span class="line"><span>│   ├── team=data     → slack-data</span></span>
<span class="line"><span>│   ├── team=infra    → slack-infra</span></span>
<span class="line"><span>│   └── (fallback)    → slack</span></span>
<span class="line"><span>└── severity=info     → slack-info</span></span></code></pre></div><p>Silences (<code>src/silence/index.ts</code>).</p><ul><li><code>silence-maintenance-platform</code> — literal <code>team=platform</code> for 15 min</li><li><code>silence-deploy-window</code> — regex <code>route=^/api/</code> for 30 min</li></ul><p>Escalation ladder (<code>src/escalation/index.ts</code>).</p><ul><li>L1 — 30 s → <code>oncall-primary</code></li><li>L2 — 5 min → <code>oncall-secondary</code></li><li>L3 — 30 min → <code>eng-manager</code></li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Provider prefix <code>@kiwa-lab/observability/</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because Prometheus AlertManager is an infrastructure primitive, not a token-priced generative call. Evaluation + routing latency samples feed <code>perf.p95Ms</code> so orchestrator performance stays visible in the report.</p><p><code>emitMetric</code> is deliberately excluded from <code>OPS_UNDER_TEST</code> — the real path is a Prometheus scrape-owned noop, so counting it as an op would over-report divergences. The mock adapter still accepts it (it appends to the collector so the rule engine has data to fire against); the real adapter records <code>ALERTMANAGER_METRIC_NOOP</code> in the trace.</p><p>Rate + anomaly rule kinds compile down to threshold checks at emit time — rate divides <code>(latest.value - windowStart.value) / (windowMs / 1000)</code> and pushes the derived scalar under a synthetic <code>__derived.rate.{rule-id}</code> metric; anomaly tracks a rolling mean + variance (Welford one-pass) and pushes <code>latest - (mean + stddevMult × stddev)</code> under <code>__derived.anomaly.{rule-id}</code>. The underlying <code>@kiwa-lab/observability</code> <code>AlertRouter</code> then fires on the derived scalar via the same operator + threshold predicate the threshold path uses.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>packages/observability/src/alert.ts</code> — v1.17-1 <code>AlertRouter</code> implementation</li><li><code>examples/dogfood-observability-dashboard/</code> — v1.17-2 Grafana dashboard dogfood</li><li><code>docs/quality-reports/observability/dashboard.md</code> — v1.17-2 canonical fidelity report</li><li><code>docs/quality-reports/perf/dogfood-alert-orchestrator.md</code> — perf 3-layer report (mock)</li><li><code>docs/quality-reports/perf/dogfood-alert-orchestrator.live.md</code> — perf 3-layer report (live)</li></ul>`,32)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
